{id:'shanghai',name:'上海',x:28,y:18,pop:2487,coastal:1180,defense:44},{id:'ningbo',name:'寧波',x:29,y:27,pop:1286,coastal:620,defense:42},{id:'fuzhou',name:'福州',x:27,y:42,pop:850,coastal:400,defense:38},{id:'xiamen',name:'廈門',x:25,y:53,pop:514,coastal:250,defense:40},{id:'hongkong',name:'香港',x:20,y:63,pop:750,coastal:430,defense:58},{id:'macau',name:'澳門',x:18,y:64,pop:68,coastal:42,defense:48},{id:'guangzhou',name:'廣州',x:16,y:59,pop:1880,coastal:520,defense:46},{id:'shenzhen',name:'深圳',x:19,y:61,pop:1768,coastal:700,defense:44},{id:'shantou',name:'汕頭',x:23,y:56,pop:555,coastal:280,defense:36},{id:'taipei',name:'台北',x:32,y:48,pop:654,coastal:300,defense:52},{id:'kaohsiung',name:'高雄',x:31,y:61,pop:277,coastal:170,defense:47},{id:'naha',name:'那霸',x:48,y:36,pop:32,coastal:20,defense:50},{id:'manila',name:'馬尼拉',x:42,y:82,pop:1392,coastal:610,defense:35}
