export const MODES={tutorial:{label:'教學',ap:5,resources:1.35,intel:.8,noise:.55,heat:-.5},standard:{label:'標準',ap:3,resources:1,intel:.52,noise:1,heat:0},expert:{label:'專家',ap:3,resources:.8,intel:.38,noise:1.45,heat:.5},apocalypse:{label:'末日',ap:2,resources:.65,intel:.25,noise:1.8,heat:1.4}};
export const WEAPONS=[
{id:'satellite',name:'軌道能量衛星',icon:'🛰️',energy:26,power:22,cooldown:3,success:.68,desc:'削弱核心對流'},
{id:'drones',name:'無人機群',icon:'🚁',energy:12,power:9,cooldown:1,success:.82,desc:'提升情報並干預'},
{id:'ion',name:'電離層加熱塔',icon:'⚡',energy:18,power:13,cooldown:2,success:.58,desc:'改變高空引導氣流'},
{id:'cooling',name:'海洋降溫裝置',icon:'🌊',energy:20,power:16,cooldown:2,success:.72,desc:'降低前方海域溫度'},
{id:'seeding',name:'高空凝結劑投放',icon:'✈️',energy:14,power:11,cooldown:2,success:.63,desc:'破壞風眼結構'}
];
export function rng(seed){let s=(Number(seed)||1)>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
export function bearingName(dx,dy){const a=Math.atan2(dy,dx)*180/Math.PI;const names=['東','東南東','東南','南南東','南','南南西','西南','西南西','西','西北西','西北','北北西','北','北北東','東北','東北東'];return names[Math.round(((a+360)%360)/22.5)%16]}
export function createGame(seed,modeKey='standard'){
 const random=rng(seed),mode=MODES[modeKey]||MODES.standard;const x=76+random()*12,y=62+random()*18;const wind=120+random()*55+(modeKey==='apocalypse'?35:0);const resources={people:Math.round(124780*mode.resources),supplies:Math.round(86540*mode.resources),fuel:Math.round(72300*mode.resources),power:Math.round(78*mode.resources),medical:Math.round(12650*mode.resources),energy:Math.round(86*mode.resources)};
 return{version:1,seed:String(seed),modeKey,turn:1,maxTurns:16,hour:3,day:14,month:7,year:2087,ap:mode.ap,maxAp:mode.ap,intel:mode.intel,resources,selectedCity:'hongkong',phase:0,gameOver:false,totalDeaths:0,totalDamage:0,log:[],cities:CITY_DATA.map(c=>({...c,evac:0,supplies:50,medical:60,power:78,traffic:15,status:'normal',deaths:0})),weapons:WEAPONS.map(w=>({...w,remaining:0})),storm:{name:'天鴻',code:`TY-${String(Math.floor(1000+random()*8999)).slice(-4)}`,x,y,lat:8+(100-y)*.22,lng:118+x*.37,wind,pressure:1010-wind*.34,speed:14+random()*8,radius:110+wind*.45,seaTemp:29.4+random()*1.8+mode.heat,heading:Math.PI+(.4-random()*.35),history:[{x,y}],forecast:[]},randomState:Math.floor(random()*1e9)}
}
function deterministic(game,salt){return rng(Number(game.seed)+game.turn*7919+salt)()}
export function updateForecast(game){const pts=[];let x=game.storm.x,y=game.storm.y,h=game.storm.heading;const mode=MODES[game.modeKey];for(let i=1;i<=5;i++){const n=(deterministic(game,100+i)-.5)*mode.noise*(1.15-game.intel);h+=(n*.34)-.025;x+=Math.cos(h)*(5.3+i*.25);y+=Math.sin(h)*(4.7+i*.18);pts.push({x,y,spread:4+i*(10-game.intel*7),turn:game.turn+i})}game.storm.forecast=pts;return game}
export function nearestCity(game,x=game.storm.x,y=game.storm.y){let best=null,dist=Infinity;for(const c of game.cities){const d=Math.hypot(c.x-x,c.y-y);if(d<dist){dist=d;best=c}}return{city:best,dist}}
export function riskForCity(game,city){const d=Math.hypot(city.x-game.storm.x,city.y-game.storm.y);const track=game.storm.forecast.reduce((m,p)=>Math.min(m,Math.hypot(city.x-p.x,city.y-p.y)),99);return Math.max(0,Math.min(100,Math.round(115-Math.min(d,track)*5+game.storm.wind*.08)))}
export function applyCityAction(game,action){if(game.ap<=0)return{ok:false,msg:'本回合行動點已用盡'};const city=game.cities.find(c=>c.id===game.selectedCity);if(!city)return{ok:false,msg:'請先選擇城市'};if(action==='evacuate'){if(game.resources.fuel<2500||game.resources.people<3000)return{ok:false,msg:'運輸資源不足'};city.evac=Math.min(100,city.evac+18);city.traffic=Math.min(100,city.traffic+14);city.status='evacuating';game.resources.fuel-=2500;game.resources.people-=3000}
 if(action==='defend'){if(game.resources.supplies<3500)return{ok:false,msg:'物資不足'};city.defense=Math.min(100,city.defense+14);game.resources.supplies-=3500}
 if(action==='supply'){if(game.resources.supplies<2500||game.resources.medical<300)return{ok:false,msg:'補給不足'};city.supplies=Math.min(100,city.supplies+18);city.medical=Math.min(100,city.medical+12);game.resources.supplies-=2500;game.resources.medical-=300}
 if(action==='intel'){if(game.resources.power<4)return{ok:false,msg:'電力不足'};game.intel=Math.min(.95,game.intel+.12);game.resources.power-=4}
 game.ap--;game.log.push(`回合 ${game.turn}：對${city.name}執行${action}`);return{ok:true,msg:`${city.name}部署完成`}}
export function useWeapon(game,id){const w=game.weapons.find(x=>x.id===id);if(!w||w.remaining>0)return{ok:false,msg:'武器仍在冷卻'};if(game.ap<=0)return{ok:false,msg:'本回合行動點已用盡'};if(game.resources.energy<w.energy)return{ok:false,msg:'氣象武器能源不足'};game.resources.energy-=w.energy;game.ap--;w.remaining=w.cooldown;const chance=w.success+(game.intel-.5)*.18;const success=deterministic(game,500+WEAPONS.findIndex(x=>x.id===id))<chance;if(success){game.storm.wind=Math.max(55,game.storm.wind-w.power);game.storm.pressure=Math.min(1005,game.storm.pressure+w.power*.18);if(id==='drones')game.intel=Math.min(.95,game.intel+.1);if(id==='ion')game.storm.heading+=(deterministic(game,614)-.5)*.45;if(id==='cooling')game.storm.seaTemp-=.9;game.log.push(`回合 ${game.turn}：${w.name}成功`);return{ok:true,msg:`${w.name}干預成功，風暴受到削弱`}}game.storm.wind+=id==='ion'?8:3;game.log.push(`回合 ${game.turn}：${w.name}失敗`);return{ok:true,msg:`${w.name}干預失敗，風暴出現反應`}}
export function advanceTurn(game){if(game.gameOver)return game;const mode=MODES[game.modeKey];const r=deterministic(game,700);const steering=(r-.5)*.34*mode.noise;game.storm.heading+=steering-.02;const step=4.5+game.storm.speed/10;game.storm.x+=Math.cos(game.storm.heading)*step;game.storm.y+=Math.sin(game.storm.heading)*step*.78;game.storm.x=Math.max(5,Math.min(96,game.storm.x));game.storm.y=Math.max(5,Math.min(96,game.storm.y));game.storm.lat=8+(100-game.storm.y)*.22;game.storm.lng=118+game.storm.x*.37;const overLand=game.storm.x<34&&game.storm.y<76;const heatGain=(game.storm.seaTemp-28.3)*5.8;game.storm.wind+=overLand?-(16+deterministic(game,708)*14):heatGain+(deterministic(game,709)-.5)*12;game.storm.wind=Math.max(45,Math.min(330,game.storm.wind));game.storm.pressure=Math.max(875,Math.min(1004,1010-game.storm.wind*.38));game.storm.radius=95+game.storm.wind*.55;game.storm.history.push({x:game.storm.x,y:game.storm.y});
 for(const c of game.cities){if(c.status==='evacuating'){const progress=Math.max(3,14-c.traffic*.06+c.supplies*.03);c.evac=Math.min(100,c.evac+progress);c.traffic=Math.max(12,c.traffic-4)}c.power=Math.max(0,c.power-(deterministic(game,800+c.x)-.5)*4)}
 const near=nearestCity(game);if(near.dist<12&&game.storm.wind>90){const c=near.city;const intensity=(game.storm.wind-80)/2.2;const mitigation=c.defense*.52+c.evac*.42+c.supplies*.12;const damage=Math.max(0,intensity-mitigation);const deaths=Math.round(Math.max(0,damage)*c.coastal*(1-c.evac/115)*.18);c.deaths+=deaths;c.status=damage>40?'critical':'damaged';game.totalDeaths+=deaths;game.totalDamage+=Math.round(damage);c.power=Math.max(0,c.power-damage*.6)}
 game.weapons.forEach(w=>w.remaining=Math.max(0,w.remaining-1));game.turn++;game.hour+=6;if(game.hour>=24){game.hour-=24;game.day++}game.ap=game.maxAp;const eventRoll=deterministic(game,900);let event=null;if(eventRoll<.18){game.intel=Math.max(.18,game.intel-.12);event='雷達資料中斷，預測可信度下降'}else if(eventRoll<.34){game.resources.supplies+=4200;event='國際支援物資已抵達'}else if(eventRoll<.48){game.storm.seaTemp+=.6;event='颱風進入暖水渦旋，強度可能急升'}else if(eventRoll<.60){const c=game.cities[Math.floor(deterministic(game,940)*game.cities.length)];c.traffic=Math.min(100,c.traffic+30);event=`${c.name}撤離道路嚴重擠塞`}
 updateForecast(game);if(game.storm.x<33||game.turn>game.maxTurns||game.storm.wind<65){game.gameOver=true}return{game,event}}
export function gradeGame(game){const avgEvac=game.cities.reduce((s,c)=>s+c.evac,0)/game.cities.length;const avgDefense=game.cities.reduce((s,c)=>s+c.defense,0)/game.cities.length;const score=Math.max(0,Math.round(1000-game.totalDeaths*.02-game.totalDamage*2+avgEvac*2+avgDefense*1.2+game.resources.energy));let grade='F',title='文明崩潰';if(score>=950){grade='S';title='人類守護者'}else if(score>=800){grade='A';title='危機指揮官'}else if(score>=650){grade='B';title='防災專家'}else if(score>=500){grade='C';title='勉強守住'}else if(score>=330){grade='D';title='重大災難'}return{score,grade,title,avgEvac:Math.round(avgEvac),avgDefense:Math.round(avgDefense)}}
